        public void DivMat()
        {
            int rows = 8;
            int cols = 8;
            int totalElements = rows * cols;

            shortMxN a = GenerateOP.shortMat(rows, cols, 10);

            shortComp.divInPlace(a, 2); // a /= 2

            for (int i = 0; i < totalElements; i++)
                Assert.IsTrue(a[i] == (short)5);

            shortComp.divInPlace(5, a); // a = 5 / a

            for (int i = 0; i < totalElements; i++)
